        if (diff.TotalMinutes < 60) return $"{(int)diff.TotalMinutes} min ago";
        if (diff.TotalHours < 24) return $"{(int)diff.TotalHours}h ago";
        if (diff.TotalDays < 7) return $"{(int)diff.TotalDays}d ago";
        return sentAt.ToString("MMM d");
    }
}

@page "/chat"
@using sv_79bbc819a783447b8620d79e7e7ac537.Services
@inject IChatService ChatService
@rendermode InteractiveServer

<PageTitle>Chat</PageTitle>

<div class="chat-layout @(isThreadOpen ? "thread-open" : "")">
    <ChannelSidebar Channels="channels"
                    ActiveChannelId="activeChannelId"
                    OnChannelSelected="SelectChannel" />

    @if (activeChannel is not null)
    {
        <MessageArea ChannelName="@activeChannel.Name"
                     ChannelDescription="@activeChannel.Description"
                     Messages="messages"
                     ThreadReplyCounts="threadReplyCounts"
                     IsLoadingMore="isLoadingMore"
                     OnLoadMore="LoadOlderMessages"
                     OnOpenThread="OpenThread"
                     OnReact="HandleReaction"
                     OnSendMessage="SendMessage" />
    }

    @if (isThreadOpen)
    {
        <ThreadPanel RootMessage="threadRootMessage"
                     Replies="threadReplies"
                     OnClose="CloseThread"
                     OnReply="SendThreadReply" />
    }
</div>

@code {
    private List<Channel> channels = new();
    private int activeChannelId;
    private Channel? activeChannel;
    private List<Message> messages = new();
    private Dictionary<int, int> threadReplyCounts = new();
    private bool isLoadingMore;

    // Thread state
    private bool isThreadOpen;
    private Message? threadRootMessage;
    private List<Message> threadReplies = new();

    private const int PageSize = 30;

    protected override async Task OnInitializedAsync()
    {
        channels = await ChatService.GetChannelsAsync();
        if (channels.Count > 0)
        {
            await SelectChannel(channels[0].Id);
        }
    }

    private async Task SelectChannel(int channelId)
    {
        activeChannelId = channelId;
        activeChannel = channels.FirstOrDefault(c => c.Id == channelId);
        messages = await ChatService.GetMessagesAsync(channelId, 0, PageSize);
        await ChatService.MarkChannelReadAsync(channelId);
        await LoadThreadCounts();
        CloseThreadSync();
    }

    private async Task LoadThreadCounts()
    {
        threadReplyCounts.Clear();
        // Identify messages that could be thread roots (those with no ReplyToId)
        var potentialRoots = messages.Where(m => m.ReplyToId is null).Select(m => m.Id).ToList();
        foreach (var rootId in potentialRoots)
        {
            var thread = await ChatService.GetThreadAsync(rootId);
            if (thread.Count > 0)
            {
                threadReplyCounts[rootId] = thread.Count;
            }
        }
    }

    private async Task LoadOlderMessages()
    {
        if (isLoadingMore) return;
        isLoadingMore = true;
        StateHasChanged();

        var older = await ChatService.GetMessagesAsync(activeChannelId, messages.Count, PageSize);
        if (older.Count > 0)
        {
            messages.InsertRange(0, older);
        }

        isLoadingMore = false;
    }

    private async Task SendMessage(string content)
    {
        var message = await ChatService.SendMessageAsync(activeChannelId, content, null);
        messages.Add(message);
    }

    private async Task OpenThread(int messageId)
    {
        threadRootMessage = messages.FirstOrDefault(m => m.Id == messageId);
        if (threadRootMessage is null) return;

        threadReplies = await ChatService.GetThreadAsync(messageId);
        isThreadOpen = true;
    }

    private void CloseThreadSync()
    {
        isThreadOpen = false;
        threadRootMessage = null;
        threadReplies = new();
    }

    private Task CloseThread()
    {
        CloseThreadSync();
        return Task.CompletedTask;
    }

    private async Task SendThreadReply(string content)
    {
        if (threadRootMessage is null) return;
        var reply = await ChatService.SendMessageAsync(activeChannelId, content, threadRootMessage.Id);
        threadReplies.Add(reply);

        // Update reply count
        threadReplyCounts[threadRootMessage.Id] = threadReplies.Count;
    }

    private async Task HandleReaction((int MessageId, string Emoji) reaction)
    {
        await ChatService.AddReactionAsync(reaction.MessageId, reaction.Emoji);
        // Refresh messages to reflect the new reaction
        messages = await ChatService.GetMessagesAsync(activeChannelId, 0, messages.Count);
    }
}

