toolArgs.file_text:
/* Layout */
.chat-layout {
    display: grid;
    grid-template-columns: 20% 1fr;
    height: 100vh;
    overflow: hidden;
}

.chat-layout.thread-open {
    grid-template-columns: 20% 1fr 25%;
}

/* Channel Sidebar */
::deep .channel-sidebar {
    background: #2b2d31;
    color: #f2f3f5;
    padding: 1rem 0;
    overflow-y: auto;
    border-right: 1px solid #1e1f22;
}

::deep .sidebar-title {
    padding: 0 1rem;
    margin: 0 0 0.75rem;
    font-size: 0.85rem;
    text-transform: uppercase;
    letter-spacing: 0.05em;
    color: #b5bac1;
}

::deep .channel-list {
    display: flex;
    flex-direction: column;
}

::deep .channel-item {
    display: flex;
    flex-wrap: wrap;
    align-items: center;
    gap: 0.25rem;
    padding: 0.5rem 1rem;
    cursor: pointer;
    border-radius: 4px;
    margin: 0 0.5rem;
    transition: background 0.15s;
}

::deep .channel-item:hover {
    background: #35373c;
}

::deep .channel-item.active {
    background: #404249;
}

::deep .channel-name {
    font-weight: 600;
    font-size: 0.95rem;
    flex: 1;
}

::deep .channel-description {
    width: 100%;
    font-size: 0.75rem;
    color: #b5bac1;
    white-space: nowrap;
    overflow: hidden;
    text-overflow: ellipsis;
}

::deep .unread-badge {
    background: #f23f43;
    color: white;
    font-size: 0.7rem;
    font-weight: 700;
    padding: 0.1rem 0.4rem;
    border-radius: 8px;
    min-width: 1.2rem;
    text-align: center;
}

/* Message Area */
::deep .message-area {
    display: flex;
    flex-direction: column;
    height: 100vh;
    background: #313338;
    color: #f2f3f5;
}

::deep .message-area-header {
    padding: 0.75rem 1rem;
    border-bottom: 1px solid #3f4147;
    flex-shrink: 0;
}

::deep .message-area-header h2 {
    margin: 0;
    font-size: 1.1rem;
}

::deep .message-area-header p {
    margin: 0.25rem 0 0;
    font-size: 0.8rem;
    color: #b5bac1;
}

::deep .message-list {
    flex: 1;
    overflow-y: auto;
    padding: 1rem;
    display: flex;
    flex-direction: column;
    gap: 0.25rem;
}

::deep .loading-indicator {
    text-align: center;
    padding: 0.5rem;
    color: #b5bac1;
    font-size: 0.85rem;
}

