+    height: 100vh;
+    background: #2b2d31;
+    color: #f2f3f5;
+    border-left: 1px solid #1e1f22;
+}
+
+::deep .thread-header {
+    display: flex;
+    justify-content: space-between;
+    align-items: center;
+    padding: 0.75rem 1rem;
+    border-bottom: 1px solid #3f4147;
+    flex-shrink: 0;
+}
+
+::deep .thread-header h3 {
+    margin: 0;
+    font-size: 1rem;
+}
+
+::deep .close-btn {
+    background: none;
+    border: none;
+    color: #b5bac1;
+    font-size: 1.2rem;
+    cursor: pointer;
+    padding: 0.2rem 0.4rem;
+    border-radius: 3px;
+    transition: background 0.15s;
+}
+
+::deep .close-btn:hover {
+    background: #404249;
+    color: #f2f3f5;
+}
+
+::deep .thread-root-message {
+    padding: 0.75rem 1rem;
+    border-bottom: 1px solid #3f4147;
+    background: #313338;
+}
+
+::deep .thread-root-message .message-author {
+    font-weight: 600;
+    font-size: 0.85rem;
+}
+
+::deep .thread-root-message .message-content {
+    margin-top: 0.25rem;
+    font-size: 0.85rem;
+    color: #dbdee1;
+}
+
+::deep .thread-replies {
+    flex: 1;
+    overflow-y: auto;
+    padding: 0.75rem 1rem;
+    display: flex;
+    flex-direction: column;
+    gap: 0.5rem;
+}
+
+::deep .thread-reply {
+    padding: 0.35rem 0;
+}
